'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const esc = (v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 14h2 M13 14h2 M7 18h2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',rx:'M5 21V3h6a4 4 0 0 1 0 8H5 M10 11l10 10 M20 12l-8 9',clock:'M12 8v4l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3 1 3 1v4l-3 1-1 3-1 3h-4l-1-3-3-1-3-1v-4l3-1 1-3z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',plus:'M12 5v14 M5 12h14',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',video:'M15 8l6-3v14l-6-3 M3 5h12v14H3z',clinic:'M3 21h18 M5 21V4h14v17 M9 21v-5h6v5 M9 8h6 M12 5v6',check:'M5 12l4 4L19 6',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',download:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',chat:'M21 11a9 9 0 0 1-9 9H3l2-4a9 9 0 1 1 16-5 M8 10h8 M8 14h5',x:'M6 6l12 12 M6 18L18 6',phone:'M7 3l3 5-2 2c2 4 3 5 6 6l2-2 5 3c-1 5-5 5-10 1S2 7 7 3',send:'M3 3l18 9-18 9 3-9z M6 12h15',menu:'M3 6h18 M3 12h18 M3 18h18',lock:'M7 11V7a5 5 0 0 1 10 0v4 M5 11h14v10H5z M12 15v3',leaf:'M20 3C8 2 2 8 5 16s15 6 15-13 M5 20L16 8',location:'M12 22s8-8 8-13a8 8 0 0 0-16 0c0 5 8 13 8 13 M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',heart:'M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1C-2 12 12 21 12 21s14-9 8-16',logout:'M9 3H3v18h6 M14 7l5 5-5 5 M8 12h12',rupee:'M5 4h14 M5 8h14 M7 4a5 5 0 0 1 0 10H5l9 7',mic:'M9 3h6v11H9z M5 10v3a7 7 0 0 0 14 0v-3 M12 20v3',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',mail:'M3 5h18v14H3z M3 5l9 7 9-7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',copy:'M9 9h12v12H9z M15 5V3H3v12h2',refresh:'M20 7v5h-5 M4 17v-5h5 M6 5a8 8 0 0 1 14 6 M4 13a8 8 0 0 0 14 6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});
const dateText=(date,opts={day:'numeric',month:'short',year:'numeric'})=>new Date(date+'T12:00:00').toLocaleDateString('en-IN',opts);
const fullDate=()=>new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'});
const initials=name=>name.split(' ').map(w=>w[0]).slice(0,2).join('');
const uid=prefix=>`${prefix}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`;
const storageKey='privatepractice-waheed-demo-v1';
const patientsSeed=[{id:'p1',name:'Ananya Sen',age:42,sex:'Female',phone:'9000000001',color:'#f1e8df',visit:'Follow-up consultation',last:'2026-10-06'},{id:'p2',name:'Ravi Sharma',age:58,sex:'Male',phone:'9000000002',color:'#e5ecda',visit:'Report review',last:'2026-10-01'},{id:'p3',name:'Fatima Ali',age:35,sex:'Female',phone:'9000000003',color:'#e9e5f0',visit:'First consultation',last:'2026-09-28'},{id:'p4',name:'Suresh Patel',age:64,sex:'Male',phone:'9000000004',color:'#e2edf0',visit:'Follow-up consultation',last:'2026-10-05'},{id:'p5',name:'Priya Das',age:47,sex:'Female',phone:'9000000005',color:'#f2e8e2',visit:'Second opinion',last:'2026-09-30'},{id:'p6',name:'Mohammed Iqbal',age:52,sex:'Male',phone:'9000000006',color:'#e9eeda',visit:'Report review',last:'2026-10-02'},{id:'p7',name:'Neha Roy',age:39,sex:'Female',phone:'9000000007',color:'#efe4e8',visit:'Follow-up consultation',last:'2026-10-07'},{id:'p8',name:'Arun Kumar',age:61,sex:'Male',phone:'9000000008',color:'#e3ece6',visit:'First consultation',last:'2026-09-24'}];
const seed=()=>({patients:patientsSeed,appointments:patientsSeed.map((p,i)=>({id:'a'+i,patientId:p.id,date:today(),time:['09:00','09:30','10:00','10:30','11:00','11:30','14:00','14:30'][i],type:[1,4,6].includes(i)?'Video':'In-clinic',status:i<2?'Completed':i===2?'In consultation':'Waiting',reason:p.visit,payment:i===4?'Paid (demo)':'Pay at clinic'})),prescriptions:[],uploads:[],settings:{clinic:'Dr. Waheed Khan’s Clinic',city:'Jamshedpur',specialty:'Oncology',fee:'1000',videoFee:'800',followFee:'600',start:'09:00',end:'17:00',duration:'30',days:['Mon','Tue','Wed','Thu','Fri','Sat'],leaveDates:[]},audit:[]});
let data;try{data=JSON.parse(localStorage.getItem(storageKey))||seed();if(!data.settings||!data.patients||!data.appointments)throw Error();data.settings.leaveDates??=[];}catch{data=seed()}
const state={mode:'doctor',view:'overview',queueTab:'All',search:'',patientSearch:'',chatOpen:false,chat:[{role:'bot',text:'Hello! I’m your clinic assistant. I can help with appointments, clinic information, and navigating the doctor workspace. How can I help?'}],portalPatient:null,calendarOffset:0,bookingType:'In-clinic',bookingSlot:'',bookingDate:today(),mobile:false,mediaStream:null};
const save=(action,detail='')=>{if(action)data.audit.unshift({id:uid('event'),at:new Date().toISOString(),action,detail});try{localStorage.setItem(storageKey,JSON.stringify(data));}catch{toast('Browser storage is unavailable. Changes last only in this session.')}};
const patientById=id=>data.patients.find(p=>p.id===id);
const todayAppointments=()=>data.appointments.filter(a=>a.date===today()).sort((a,b)=>a.time.localeCompare(b.time));
const readableTime=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const btn=(text,action,type='secondary',ic='')=>`<button class="btn btn-${type}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const avatar=p=>`<span class="avatar" style="background:${p.color||'#e5ecd9'}">${esc(initials(p.name))}</span>`;
const specialty='Oncologist';
function sidebar(){const items=[['overview','grid','Overview'],['appointments','calendar','Appointments'],['patients','users','Patients'],['prescriptions','rx','Prescriptions'],['schedule','clock','Schedule']];return `<aside class="sidebar ${state.mobile?'open':''}" aria-label="Doctor navigation"><button class="brand" data-action="view:overview"><img class="brand-mark" src="mark.svg" alt="">PrivatePractice<span style="color:#9bad7d;font-size:22px">.</span></button><p class="brand-sub">YOUR PRACTICE. YOUR PEOPLE.</p><p class="nav-label">Workspace</p>${items.map(([view,ic,label])=>`<button class="nav-item ${state.view===view?'active':''}" data-action="view:${view}" ${state.view===view?'aria-current="page"':''}>${icon(ic)}${label}${view==='appointments'?`<span class="nav-count">${todayAppointments().length}</span>`:''}</button>`).join('')}<div class="nav-divider"></div><p class="nav-label">Your clinic</p><button class="nav-item" data-action="mode:public">${icon('globe')}Public website${icon('arrow','arrow')}</button><button class="nav-item ${state.view==='settings'?'active':''}" data-action="view:settings">${icon('settings')}Practice settings</button><div class="ownership"><div class="ownership-title">${icon('shield')}Your data stays yours.</div><p>Built around your clinic. No ads.<br>No shared patient network.</p><button data-action="view:settings">Explore data ownership ${icon('arrow')}</button></div><div class="profile"><span class="avatar" style="background:#e6ecda">WK</span><div><strong>Dr. Waheed Khan</strong><small>Oncologist · Jamshedpur</small></div></div></aside>`}
function modeSwitch(){return `<div class="view-switch" aria-label="Demo experience"><button data-action="mode:doctor" class="${state.mode==='doctor'?'active':''}">Doctor</button><button data-action="mode:patient" class="${state.mode==='patient'?'active':''}">Patient</button><button data-action="mode:public" class="${state.mode==='public'?'active':''}">Website</button></div>`}
function topbar(){return `<header class="topbar"><button class="icon-btn mobile-menu" data-action="mobile" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${({overview:'Overview',appointments:'Appointments',patients:'Patients',prescriptions:'Prescriptions',schedule:'Schedule',settings:'Practice settings'})[state.view]}</strong></div><div class="top-actions">${modeSwitch()}<button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}<span class="notification-dot"></span></button><span class="avatar" style="width:30px;height:30px;font-size:10px">WK</span></div></header>`}
const plantArt=()=>`<svg class="banner-art" viewBox="0 0 245 135" fill="none" aria-hidden="true"><circle cx="169" cy="62" r="63" fill="#e0e9cd"/><path d="M136 122V63m0 33c-30-2-42-19-34-29 16-2 29 8 34 29m0-14c27-3 42-22 32-34-18 0-30 15-32 34m0-19c-4-24 1-44 13-45 12 15 3 36-13 45" stroke="#7e9668" stroke-width="2"/><path d="M113 112h46l-7 23h-32z" fill="#bdc99f"/><rect x="24" y="66" width="62" height="66" rx="8" fill="#f7f9ef" transform="rotate(-8 24 66)"/><rect x="33" y="80" width="44" height="6" rx="3" fill="#d4dfc3" transform="rotate(-8 33 80)"/><path d="M42 96l7 6 13-18" stroke="#98b17b" stroke-width="2"/><rect x="179" y="81" width="42" height="44" rx="10" fill="#f3f7e9"/><path d="M200 91v24m-12-12h24" stroke="#9bb580" stroke-width="5" stroke-linecap="round"/><circle cx="71" cy="40" r="8" stroke="#bdccaa" stroke-width="2"/><path d="M195 21h10m-5-5v10" stroke="#adbfa0" stroke-width="2"/></svg>`;
function pageHead(title,sub,action='booking',button='New appointment',ic='plus'){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action?btn(button,action,'primary',ic):''}</div>`}
function queuePanel(full=false){const all=todayAppointments();let list=all.filter(a=>state.queueTab==='All'||a.type===state.queueTab).filter(a=>{const p=patientById(a.patientId);return (p.name+' '+p.phone).toLowerCase().includes(state.search.toLowerCase())});const visible=full?list:list.slice(0,6);return `<section class="panel"><div class="panel-head"><div><h2>${full?'Appointment queue':'Today’s appointments'}</h2><p>${all.filter(a=>a.status==='Waiting').length} patients waiting · A little care goes a long way</p></div><span class="date-chip">${icon('calendar')}${dateText(today(),{day:'numeric',month:'short',year:'numeric'})}</span></div><div class="tabs-row"><div class="tabs" role="tablist" aria-label="Consultation type">${['All','In-clinic','Video'].map(t=>`<button role="tab" aria-selected="${state.queueTab===t}" class="${state.queueTab===t?'active':''}" data-action="filter:${t}">${t==='All'?'All appointments':t}<span>${all.filter(a=>t==='All'||a.type===t).length}</span></button>`).join('')}</div><div class="mini-search">${icon('search')}<input aria-label="Search appointments" placeholder="Search patients…" id="queue-search" value="${esc(state.search)}"></div></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Time</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody>${visible.map(a=>{const p=patientById(a.patientId),statusClass=a.status==='In consultation'?'consultation':a.status.toLowerCase();return `<tr><td><div class="patient-cell">${avatar(p)}<div><strong>${esc(p.name)}</strong><small>${p.age} yrs · ${esc(p.sex)}</small></div></div></td><td><div class="time-cell"><strong>${readableTime(a.time)}</strong><small>${esc(a.reason)}</small></div></td><td><span class="type">${icon(a.type==='Video'?'video':'clinic')}${a.type}</span></td><td><span class="badge ${statusClass}">${a.status}</span></td><td>${a.status==='Completed'?`<button class="row-action" data-action="history:${p.id}">View record</button>`:a.status==='Cancelled'?`<button class="row-action" data-action="booking">Rebook</button>`:`<button class="row-action ${a.status==='In consultation'?'primary':''}" data-action="consult:${a.id}">${a.status==='In consultation'?'Continue':'Start visit'}</button>`}</td></tr>`}).join('')||'<tr><td colspan="5"><div class="empty-state">No appointments match this search.</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>Showing ${visible.length} of ${list.length} appointments</span>${!full?'<button class="btn btn-quiet" data-action="view:appointments">View all appointments '+icon('arrow')+'</button>':'<span>All times in IST</span>'}</div></section>`}
function overview(){const appts=todayAppointments(),completed=appts.filter(a=>a.status==='Completed').length,waiting=appts.filter(a=>a.status==='Waiting').length;const next=appts.find(a=>a.status==='Waiting'),p=next&&patientById(next.patientId);return `${pageHead('Your day, at a glance.',fullDate()+' · All times in IST')}<section class="greeting-banner"><div><span class="eyebrow">${icon('leaf')}Care starts with connection</span><h2>Welcome back, Dr. Khan.</h2><p>You have ${appts.length} appointments today. Your workspace is ready,<br class="desktop-br"> so you can focus on the people who need you.</p></div>${plantArt()}</section><div class="stats">${[['Today’s appointments',appts.length,'calendar','',`${appts.filter(a=>a.type==='In-clinic').length} in-clinic · ${appts.filter(a=>a.type==='Video').length} video`],['Patients waiting',waiting,'clock','peach','Ready when you are'],['Completed visits',completed,'check','blue',`${appts.length?Math.round(completed/appts.length*100):0}% of today’s appointments`],['Patient records',data.patients.length,'users','purple','In your clinic’s workspace']].map(([label,value,ic,color,note])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(ic)}</span></div><div class="stat-value">${String(value).padStart(2,'0')}</div><div class="stat-bottom">${note}</div></div>`).join('')}</div><div class="workspace-grid"><div>${queuePanel()}</div><aside class="right-stack"><section class="next-card"><span class="eyebrow">Up next ${icon('arrow')}</span><h3>${next?'A conversation that matters.':'You’re all caught up.'}</h3><p>${next?'Your next patient is ready for you.':'No more patients waiting today.'}</p>${next?`<div class="next-person">${avatar(p)}<div><strong>${esc(p.name)}</strong><small>${esc(next.reason)}</small></div></div><div class="next-info"><span class="flex">${icon('clock')}${readableTime(next.time)}</span><span class="flex">${icon(next.type==='Video'?'video':'clinic')}${next.type}</span></div>${btn(next.type==='Video'?'Start video consultation':'Begin consultation','consult:'+next.id,'primary',next.type==='Video'?'video':'arrow')}`:btn('Book an appointment','booking','primary','plus')}</section><section class="panel quick-card"><h3>A few helpful shortcuts</h3>${[['rx','Write a prescription','new-rx'],['users','Add a new patient','add-patient'],['clock','Manage your availability','view:schedule']].map(([ic,label,action])=>`<button class="quick-action" data-action="${action}"><span class="quick-icon">${icon(ic)}</span>${label}${icon('chevron','arrow')}</button>`).join('')}</section><section class="panel calendar-panel"><div class="flex space"><h3>This week</h3><button class="btn btn-quiet" data-action="view:schedule">${icon('arrow')}</button></div>${weekStrip()}<div class="schedule-item"><span class="schedule-dot"></span>Clinic hours · ${readableTime(data.settings.start)} – ${readableTime(data.settings.end)}</div><div class="schedule-item"><span class="schedule-dot peach"></span>Lunch break · 1:00 – 2:00 PM</div></section></aside></div><div class="bottom-note"><span class="flex">${icon('shield')}An independent practice. A personal connection.</span><span class="demo-pill">Interactive demo · Fictional patient data</span><span>Made for thoughtful care</span></div>`}
function weekStrip(){const start=new Date();start.setDate(start.getDate()-start.getDay()+1);return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `<div class="week-day ${d.toDateString()===new Date().toDateString()?'selected':''}">${d.toLocaleDateString('en-IN',{weekday:'short'}).slice(0,1)}<strong>${d.getDate()}</strong></div>`}).join('')}</div>`}
function appointmentsView(){const future=data.appointments.filter(a=>a.date!==today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `${pageHead('Appointments', 'A clear queue. A calmer clinic.')}${queuePanel(true)}${future.length?`<section class="panel" style="margin-top:23px"><div class="panel-head"><h2>Other dates</h2><span class="muted" style="font-size:11px">${future.length} appointment(s)</span></div>${future.map(a=>{const p=patientById(a.patientId);return `<div class="record-item"><div class="patient-cell">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${dateText(a.date)} · ${readableTime(a.time)} · ${a.type}</p></div></div><div class="flex"><span class="badge ${a.status.toLowerCase()}">${a.status}</span>${a.status==='Waiting'?`<button class="row-action" data-action="cancel:${a.id}">Cancel</button>`:''}</div></div>`}).join('')}</section>`:''}`}
function patientsView(){const patients=data.patients.filter(p=>(p.name+' '+p.phone).toLowerCase().includes(state.patientSearch.toLowerCase()));return `${pageHead('People, beyond the records.', 'Your patient relationships, all in one place.','add-patient','Add patient','users')}<div class="flex space" style="margin-bottom:22px"><span class="muted" style="font-size:12px">${patients.length} patient${patients.length===1?'':'s'} · Fictional demo records</span><div class="search-large">${icon('search')}<input id="patient-search" value="${esc(state.patientSearch)}" aria-label="Search by name or phone" placeholder="Search name or phone…"></div></div><div class="patient-grid">${patients.map(p=>`<article class="panel patient-card"><div class="flex space">${avatar(p)}<span class="demo-pill">Patient record</span></div><h3>${esc(p.name)}</h3><p>${p.age} years · ${esc(p.sex)}<br>+91 ${esc(p.phone)}</p><div class="card-bottom"><small class="muted">${data.appointments.filter(a=>a.patientId===p.id).length} visit(s)</small><button class="btn btn-quiet" data-action="history:${p.id}">View history ${icon('arrow')}</button></div></article>`).join('')||'<div class="empty-state">No patients found.</div>'}</div>`}
function prescriptionsView(){return `${pageHead('Care, clearly written.', 'Create, review, and print clinic prescriptions.','new-rx','Write prescription','rx')}<div class="panel"><div class="panel-head"><h2>Prescription library</h2><span class="demo-pill">${data.prescriptions.length} saved</span></div>${data.prescriptions.length?data.prescriptions.map(r=>`<div class="record-item"><div class="patient-cell"><span class="avatar">${icon('rx')}</span><div><h3>${esc(patientById(r.patientId)?.name||'Patient')}</h3><p>${dateText(r.date)} · ${esc(r.diagnosis||'Consultation summary')}</p></div></div>${btn('Open & print','print-rx:'+r.id,'secondary','file')}</div>`).join(''):`<div class="empty-state">${icon('rx')}<h3>A fresh page for better care.</h3><p>Create your first prescription from a patient visit or start below.</p><div style="margin-top:20px">${btn('Write a prescription','new-rx','primary','plus')}</div></div>`}</div><div class="help-card"><h3>Your clinic letterhead, automatically.</h3><p>Patient details, medicines, investigations, and follow-up appear in a clean printable document. Registration number and signature must be supplied by the doctor before clinical use.</p></div>`}
function calendarView(){const d=new Date();d.setMonth(d.getMonth()+state.calendarOffset,1);const year=d.getFullYear(),month=d.getMonth(),offset=(d.getDay()+6)%7;const base=new Date(year,month,1-offset);return `${pageHead('Make room for good care.','Clinic hours, appointments, and time for yourself.','availability','Edit availability','settings')}<div class="flex space" style="margin-bottom:22px"><h2>${d.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h2><div class="month-controls"><button class="icon-btn" data-action="month:-1" aria-label="Previous month" style="transform:rotate(180deg)">${icon('chevron')}</button>${btn('Today','month:today','secondary')}<button class="icon-btn" data-action="month:1" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<div class="calendar-label">${day}</div>`).join('')}${Array.from({length:42},(_,i)=>{const day=new Date(base);day.setDate(base.getDate()+i);const date=day.toLocaleDateString('en-CA'),appts=data.appointments.filter(a=>a.date===date&&a.status!=='Cancelled');const closed=data.settings.leaveDates.includes(date)||!data.settings.days.includes(day.toLocaleDateString('en-IN',{weekday:'short'}));return `<button class="calendar-day ${day.getMonth()!==month?'outside':''} ${date===today()?'today':''}" data-action="day:${date}" aria-label="${dateText(date)}, ${appts.length} appointments"><strong>${day.getDate()}</strong>${appts.length?`<div class="calendar-event">${appts.length} appointment(s)</div>`:''}${closed?'<div class="calendar-event" style="background:#f3eee5;color:#a0947e">Unavailable</div>':''}</button>`}).join('')}</div><div class="help-card"><div class="flex space"><div><h3>Your current clinic hours</h3><p style="margin-bottom:0">${esc(data.settings.days.join(', '))} · ${readableTime(data.settings.start)} – ${readableTime(data.settings.end)} IST · ${data.settings.duration}-minute slots</p></div>${btn('Block a day','leave','secondary','calendar')}</div></div>`}
function settingsView(){return `${pageHead('A practice of your own.','Your identity, your availability, your data.','','')}<div class="settings-grid"><div><form id="settings-form" class="panel settings-section"><h3>Clinic essentials</h3><p>These details appear on your website and booking flow. Fees below are illustrative and editable.</p><div class="field-grid"><div class="field"><label for="clinic-name">Clinic name</label><input id="clinic-name" name="clinic" value="${esc(data.settings.clinic)}" required></div><div class="field"><label for="clinic-city">City</label><input id="clinic-city" name="city" value="${esc(data.settings.city)}" required></div></div><div class="field-grid"><div class="field"><label for="clinic-fee">In-clinic fee (₹)</label><input id="clinic-fee" name="fee" type="number" min="0" value="${esc(data.settings.fee)}" required></div><div class="field"><label for="video-fee">Video fee (₹)</label><input id="video-fee" name="videoFee" type="number" min="0" value="${esc(data.settings.videoFee)}" required></div></div><div class="field"><label for="follow-fee">Follow-up fee (₹)</label><input id="follow-fee" name="followFee" type="number" min="0" value="${esc(data.settings.followFee)}" required></div><button class="btn btn-primary" type="submit">${icon('check')}Save clinic details</button></form><section class="panel settings-section"><h3>Your data controls</h3><p>This prototype stores fictional records in this browser. Export includes patients, appointments, prescriptions, settings, and the demo activity log.</p><div class="flex" style="flex-wrap:wrap">${btn('Export demo data','export','secondary','download')}${btn('View activity log','audit','secondary','clock')}${btn('Reset demo','reset','danger','refresh')}</div></section></div><aside><section class="panel settings-section"><span class="eyebrow">${icon('shield')}Ownership by design</span><h3 style="margin-top:15px">Care without compromise.</h3>${[['lock','Clinic-controlled access','Production requires a doctor-owned database, authentication, and access policies.'],['file','Private medical records','Encrypted private storage and time-limited file access belong in the production backend.'],['download','An open exit','Export your demo records anytime, without a proprietary file format.'],['eye','A visible trail','Review changes in the demo log. A tamper-resistant audit trail requires server-side storage.']].map(([ic,title,desc])=>`<div class="data-feature">${icon(ic)}<div>${title}<small>${desc}</small></div></div>`).join('')}</section><div class="form-note">Demo mode has no real authentication, encrypted medical storage, payments, SMS, or remote video connection. Use fictional information only.</div></aside></div>`}
function doctorPage(){const views={overview,appointments:appointmentsView,patients:patientsView,prescriptions:prescriptionsView,schedule:calendarView,settings:settingsView};return `<div class="shell">${sidebar()}<main class="main">${topbar()}<div class="content">${(views[state.view]||overview)()}</div></main></div>`}
function doctorIllustration(){return `<svg viewBox="0 0 400 400" fill="none" role="img" aria-label="Illustrative portrait of a doctor, not a photograph of Dr. Khan"><circle cx="201" cy="152" r="122" fill="#d7e2c1"/><path d="M33 400c0-99 58-158 116-164h104c60 6 114 65 114 164" fill="#f7f8ef"/><path d="M176 218h52v49l-26 38-26-38z" fill="#bc9278"/><path d="M147 103c-2-52 31-70 57-70 48 0 67 36 58 84l-4 52c-4 38-29 65-56 65s-53-30-57-67z" fill="#ccaa8c"/><path d="M146 116c-28-72 49-105 80-77 48 0 54 51 38 83l-10-35c-29 6-60 6-83-4l-18 43" fill="#3e4938"/><path d="M163 138h27v18h-27z M213 138h27v18h-27z M190 145h23 M146 140l17 3 M240 143l19-3" stroke="#5a574a" stroke-width="3"/><path d="M197 153l-4 23h13 M185 190c10 7 22 7 33-1" stroke="#9e755c" stroke-width="2.5" stroke-linecap="round"/><path d="M149 238l-33 45 39 21-22 30 48 64 M251 238l32 45-39 21 23 30-45 64" stroke="#dce3d1" stroke-width="2"/><path d="M177 246l25 58 25-58v154h-50z" fill="#789170"/><path d="M152 247c-8 48-4 83 22 86 M248 247c8 48 4 83-22 86" stroke="#4c6651" stroke-width="3"/><path d="M175 332v11 M226 332v11" stroke="#4c6651" stroke-width="3"/><circle cx="176" cy="352" r="10" fill="#647e5b"/><rect x="268" y="321" width="52" height="14" rx="3" fill="#d6dfcd"/><path d="M279 318v-17" stroke="#7a9371" stroke-width="3"/><circle cx="71" cy="107" r="18" stroke="#b2c49c"/><path d="M71 98v18 M62 107h18" stroke="#b2c49c" stroke-width="2"/><path d="M333 162c15-2 25-11 23-25-15 1-24 10-23 25 M333 162v36" stroke="#a4b88d" stroke-width="2"/></svg>`}
function publicPage(){return `<header class="public-header"><button class="brand" data-action="mode:public"><img class="brand-mark" src="mark.svg" alt="">Dr. Waheed Khan</button><nav class="public-nav"><a href="#care">Our care</a><a href="#clinic">The clinic</a>${btn('Book a consultation','booking','primary','arrow')}</nav></header><main class="public-main"><section class="public-hero"><div><span class="eyebrow">Oncology care · ${esc(data.settings.city)}</span><h1>Expert care.<br>A human <em>connection.</em></h1><p class="lead">A conversation, a clear next step, and care that sees the whole person. Connect directly with Dr. Waheed Khan for your oncology consultation.</p><div class="hero-actions">${btn('Book a consultation','booking','primary','calendar')}${btn('Patient portal','mode:patient','secondary','arrow')}</div><div class="trust-line">${icon('shield')}Your relationship is with your doctor.</div><div class="demo-pill" style="display:inline-block;margin-top:24px">Demo website · Fees and clinic details are illustrative</div></div><div class="doctor-art">${doctorIllustration()}<div class="doctor-label"><div><h3>Dr. Waheed Khan</h3><p>Oncologist · ${esc(data.settings.city)}</p></div>${icon('heart')}</div></div></section><section class="public-section" id="care"><span class="eyebrow">Care that meets you where you are</span><h2>Start with a conversation.</h2><div class="service-grid">${[['clinic','In-clinic consultation','Meet your doctor in person to discuss your concerns, reports, and next steps.',data.settings.fee,'In-clinic'],['video','Online consultation','Speak with your doctor from home, with a scheduled video appointment.',data.settings.videoFee,'Video'],['file','Follow-up & report review','Continue the conversation and review your reports with your treating doctor.',data.settings.followFee,'Follow-up']].map(([ic,title,desc,fee,type])=>`<article class="service-card"><div class="service-icon">${icon(ic)}</div><h3>${title}</h3><p>${desc}</p><div class="price"><strong>₹${Number(fee).toLocaleString('en-IN')} <span class="muted" style="font-size:10px;font-weight:400">/ consultation · demo</span></strong><button class="icon-btn" data-action="book-type:${type}" aria-label="Book ${title}">${icon('arrow')}</button></div></article>`).join('')}</div></section><section class="public-section" id="clinic"><div class="location-grid"><div><span class="eyebrow">Your doctor, directly</span><h2>Independent care.<br>At every step.</h2><p class="lead" style="font-size:13px;line-height:1.9;color:#859175">Your appointments, records, and conversations come together in one clinic experience. This demo shows how an independently owned platform can work.</p><div class="form-note">Qualifications, registration number, full address, and clinic contact details are awaiting verification from the doctor.</div></div><div class="clinic-info"><h3>${esc(data.settings.clinic)}</h3><p class="flex">${icon('location')}${esc(data.settings.city)}, Jharkhand</p><p style="margin-top:16px">${esc(data.settings.days.join(' · '))}<br>${readableTime(data.settings.start)} – ${readableTime(data.settings.end)} IST<br>Lunch break: 1:00 – 2:00 PM</p>${btn('Find a consultation time','booking','primary','calendar')}<div style="margin-top:14px;font-size:10px;color:#8b997d">Full clinic address will be added after confirmation.</div></div></div></section><footer class="public-footer"><span>Dr. Waheed Khan · Independent oncology practice</span><div class="flex">${modeSwitch()}</div><span>Illustrative prototype · No real medical records</span></footer></main>`}
function portalPage(){const p=state.portalPatient&&patientById(state.portalPatient);if(!p)return `<header class="portal-header"><div class="brand"><img class="brand-mark" src="mark.svg" alt="">Your clinic, connected.</div>${modeSwitch()}</header><main class="portal-main"><div style="max-width:490px;margin:65px auto"><span class="eyebrow">Dr. Waheed Khan · Patient portal</span><h1 style="margin:15px 0">A little closer to your care.</h1><p class="muted" style="font-size:13px;line-height:1.9;margin-bottom:24px">Access your appointments, consultation notes, and reports in one place.</p><div class="panel" style="padding:27px"><h3>Welcome to your clinic</h3><p class="muted" style="font-size:11px;line-height:1.8;margin:10px 0 22px">Try the patient experience using a fictional patient. Real phone verification will be connected in production.</p>${btn('Try demo phone login','login','primary','phone')}<div class="form-note" style="margin-top:23px">Interactive demo only. Login does not verify identity. Please use fictional information.</div></div></div></main>`;const appts=data.appointments.filter(a=>a.patientId===p.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),rx=data.prescriptions.filter(r=>r.patientId===p.id),uploads=data.uploads.filter(u=>u.patientId===p.id);return `<header class="portal-header"><div class="brand"><img class="brand-mark" src="mark.svg" alt="">Your clinic, connected.</div><div class="flex">${modeSwitch()}<button class="icon-btn" data-action="logout" aria-label="Leave demo portal">${icon('logout')}</button></div></header><main class="portal-main"><span class="eyebrow">Patient portal · Dr. Waheed Khan</span><div class="portal-welcome"><div><h2>Hello, ${esc(p.name.split(' ')[0])}.</h2><p>Your care, a little more connected. What can we help with today?</p></div>${btn('Book a consultation','booking','primary','plus')}</div><div class="portal-grid"><section class="panel"><div class="panel-head"><div><h2>Your appointments</h2><p>All appointment times are in IST</p></div>${icon('calendar')}</div>${appts.map(a=>`<div class="record-item"><div><h3>${a.type} consultation</h3><p>${dateText(a.date)} · ${readableTime(a.time)}<br>${esc(a.reason)}</p></div><div class="flex"><span class="badge ${a.status==='In consultation'?'consultation':a.status.toLowerCase()}">${a.status}</span>${a.status==='Waiting'?`<button class="icon-btn" data-action="cancel:${a.id}" aria-label="Cancel appointment">${icon('x')}</button>`:''}</div></div>`).join('')||'<div class="empty-state">No appointments yet. Choose a time that works for you.</div>'}</section><div><section class="panel"><div class="panel-head"><h2>Your prescriptions</h2>${icon('rx')}</div>${rx.length?rx.map(r=>`<div class="record-item"><div><h3>Consultation prescription</h3><p>${dateText(r.date)}</p></div><button class="icon-btn" data-action="print-rx:${r.id}" aria-label="Open prescription">${icon('download')}</button></div>`).join(''):'<div class="empty-state" style="padding:25px">Prescriptions will appear here after your consultation.</div>'}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Bring your reports</h2><p>Demo uploads store file names only</p></div>${icon('file')}</div><label class="upload-zone">${icon('upload')}<p>Choose a PDF or image</p><small>Up to 10 MB · Files are not uploaded</small><input type="file" id="report-upload" accept=".pdf,.jpg,.jpeg,.png" aria-label="Choose a demo report"></label>${uploads.map(u=>`<div class="record-item"><div><h3>${esc(u.name)}</h3><p>${Math.round(u.size/1024)} KB · Metadata only</p></div><button class="icon-btn" data-action="remove-upload:${u.id}" aria-label="Remove report metadata">${icon('trash')}</button></div>`).join('')}</section></div></div><div class="form-note" style="margin-top:25px">You are viewing a fictional patient in demo mode. Production access will require verified login and server-enforced patient permissions.</div></main>`}
function render(){const root=$('#app');root.innerHTML=state.mode==='doctor'?doctorPage():state.mode==='public'?publicPage():portalPage();renderChat()}
function renderChat(){const root=$('#chat-root');if(!state.chatOpen){root.innerHTML=`<button class="chat-launcher" data-action="chat">${icon('spark','spark')}Clinic assistant ${icon('chat')}</button>`;return}const prompts=state.mode==='doctor'?['Today’s queue','Write a prescription','Export my data']:['Book an appointment','Clinic hours','Consultation fees'];root.innerHTML=`<section class="chat-panel" aria-label="Clinic assistant"><header class="chat-head"><div class="flex">${icon('spark')}<div><strong>Clinic assistant</strong><small>Here to make care a little easier</small></div></div><button class="icon-btn" data-action="chat" aria-label="Close clinic assistant">${icon('x')}</button></header><div class="chat-body" id="chat-body">${state.chat.map(m=>`<div class="message ${m.role}" role="${m.role==='bot'?'status':'note'}">${esc(m.text)}</div>`).join('')}<div class="chat-prompts">${prompts.map(p=>`<button data-action="prompt:${p}">${p}</button>`).join('')}</div></div><form class="chat-form" id="chat-form"><input id="chat-input" placeholder="How can I help?" aria-label="Message the clinic assistant" maxlength="1000" autocomplete="off" required><button type="submit" aria-label="Send message">${icon('send')}</button></form><div class="chat-disclaimer">Scripted demo assistant · No diagnosis or treatment advice</div></section>`;const body=$('#chat-body');body.scrollTop=body.scrollHeight}
function chatReply(text){const q=text.toLowerCase();let answer;if(/pain|symptom|diagnos|treatment|medicine|dose|dosage|cancer stage|chemotherapy|prescribe/.test(q)&&!q.includes('prescription'))answer='I can help with clinic information and appointments, but I cannot diagnose symptoms or recommend treatment. Please discuss medical concerns directly with Dr. Khan. For an urgent concern, contact local emergency services.';else if(/book|appointment|slot/.test(q)){answer='You can choose an in-clinic or video consultation, then select a date and an available time. This demo reserves a slot locally; it does not send messages or charge you. I’ve opened the booking form for you.';openBooking()}else if(/hour|timing|open|available/.test(q))answer=`Clinic hours are ${readableTime(data.settings.start)}–${readableTime(data.settings.end)} IST, ${data.settings.days.join(', ')}. Lunch is 1:00–2:00 PM. Appointment availability also reflects blocked days.`;else if(/fee|cost|price|payment|upi/.test(q))answer=`Illustrative demo fees: in-clinic ₹${data.settings.fee}, video ₹${data.settings.videoFee}, follow-up ₹${data.settings.followFee}. Real payments are not connected. In-clinic bookings can use “Pay at clinic.”`;else if(/queue|today|waiting/.test(q)){if(state.mode!=='doctor')answer='Patient queue details are available in the doctor workspace. I can help you book an appointment or find the clinic hours.';else{const a=todayAppointments();answer=`Today: ${a.length} appointments, ${a.filter(x=>x.status==='Waiting').length} waiting, ${a.filter(x=>x.status==='In consultation').length} in consultation, and ${a.filter(x=>x.status==='Completed').length} completed. Use “Start visit” beside a patient to begin.`;state.view='appointments';render()}}else if(/prescription|write.*rx/.test(q)){if(state.mode==='doctor'){answer='I’ve opened the prescription writer. Select a patient and enter your own clinical notes and medication instructions. I do not generate diagnoses or medication recommendations.';openRx()}else answer='Your saved prescriptions appear in the patient portal after the doctor completes a consultation. Choose a prescription to open it, then print or save as PDF.'}else if(/export|download.*data/.test(q)){if(state.mode==='doctor'){answer='Your demo data can be exported as JSON from Practice settings. I’ve opened your data controls.';state.view='settings';render()}else answer='You can print your own saved prescriptions from the patient portal. Clinic-wide data exports belong to the doctor workspace.'}else if(/privacy|data|ownership|secure/.test(q))answer='This prototype stores fictional records in your browser and provides a JSON export. Complete data sovereignty in production requires clinic-controlled hosting, a private database, private file storage, and server-side access controls. This demo does not provide those security guarantees.';else if(/address|location|where|contact/.test(q))answer=`Dr. Waheed Khan is an oncologist in ${data.settings.city}. The full clinic address and contact number are awaiting confirmation. I won’t invent those details.`;else if(/report|upload/.test(q)){answer='In the patient demo portal, use “Bring your reports” to choose a PDF or image. Only its name and size are saved; the actual file is not uploaded. Real private storage will be connected in production.'}else if(/hello|hi\b|thank/.test(q))answer='Hello! I can help you find clinic hours and fees, book a consultation, or navigate the demo workspace. What would you like to do?';else answer='I can help with booking, clinic hours, fees, patient report uploads, and doctor workflow shortcuts. This scripted demo does not understand every question yet. Try one of the suggestions below.';state.chat.push({role:'user',text},{role:'bot',text:answer});renderChat();if(!$('#modal-root').children.length)$('#chat-input')?.focus()}
let priorFocus=null;
function openModal(title,subtitle,body,footer='',wide=false){priorFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('#modal-root input, #modal-root select, #modal-root .btn, #modal-root .icon-btn')?.focus())}
function closeModal(){if(state.mediaStream){state.mediaStream.getTracks().forEach(t=>t.stop());state.mediaStream=null}$('#modal-root').innerHTML='';document.body.style.overflow='';priorFocus?.isConnected&&priorFocus.focus()}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function bookingSlots(date,type){const weekday=new Date(date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'short'});if(data.settings.leaveDates.includes(date)||!data.settings.days.includes(weekday))return [];const toMin=v=>v.split(':').reduce((a,b,i)=>a+Number(b)*(i?1:60),0);let result=[];for(let m=toMin(data.settings.start);m+Number(data.settings.duration)<=toMin(data.settings.end);m+=Number(data.settings.duration)){if(m<840&&m+Number(data.settings.duration)>780)continue;if(date===today()){const now=new Date();const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(now);const minute=Number(parts.find(p=>p.type==='hour').value)*60+Number(parts.find(p=>p.type==='minute').value);if(m<=minute)continue;}const time=`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;if(!data.appointments.some(a=>a.date===date&&a.time===time&&a.status!=='Cancelled'))result.push(time)}return result}
function openBooking(type){if(type)state.bookingType=type;state.bookingSlot='';state.bookingDate=state.bookingDate<today()?today():state.bookingDate;const p=state.portalPatient?patientById(state.portalPatient):null;const body=`<div class="booking-steps"><span class="active">1 · Your visit</span><span>2 · Confirmation</span></div><form id="booking-form"><label>How would you like to meet?</label><div class="option-cards">${['In-clinic','Video'].map(t=>`<button type="button" class="option-card ${state.bookingType===t?'active':''}" data-action="booking-type:${t}">${icon(t==='Video'?'video':'clinic')}<div><strong>${t==='Video'?'Video consultation':'At the clinic'}</strong><small>₹${t==='Video'?data.settings.videoFee:data.settings.fee} · Demo fee</small></div></button>`).join('')}</div><div class="field"><label for="booking-date">Choose a date · IST</label><input id="booking-date" name="date" type="date" min="${today()}" value="${state.bookingDate}" required></div><label>Available consultation times</label><div class="slot-grid" id="booking-slots"></div><input type="hidden" name="time" id="booking-time"><div class="field-grid"><div class="field"><label for="booking-name">Patient name</label><input id="booking-name" name="name" placeholder="Full name" value="${esc(p?.name||'')}" maxlength="80" required></div><div class="field"><label for="booking-phone">Mobile number</label><input id="booking-phone" name="phone" type="tel" placeholder="10-digit demo number" inputmode="numeric" pattern="[6-9][0-9]{9}" maxlength="10" value="${esc(p?.phone||'')}" title="Enter a 10-digit Indian mobile number" required></div></div><div class="field-grid"><div class="field"><label for="booking-age">Age</label><input id="booking-age" name="age" type="number" min="0" max="120" value="${p?.age||''}" required></div><div class="field"><label for="booking-sex">Sex</label><select name="sex" id="booking-sex"><option ${p?.sex==='Female'?'selected':''}>Female</option><option ${p?.sex==='Male'?'selected':''}>Male</option><option>Other</option><option>Prefer not to say</option></select></div></div><div class="field"><label for="booking-reason">Visit type</label><select name="reason" id="booking-reason"><option>First consultation</option><option>Follow-up consultation</option><option>Report review</option><option>Second opinion</option></select></div><div class="field"><label for="booking-payment">Payment preference</label><select name="payment" id="booking-payment">${state.bookingType==='In-clinic'?'<option>Pay at clinic</option>':''}<option>Online payment (demo only)</option></select></div><div id="booking-fee-summary" class="form-note"></div><div class="form-note">${icon('shield')}Fictional data only. No payment will be charged and no SMS will be sent.</div><button type="submit" class="btn btn-primary" style="width:100%">Confirm demo appointment ${icon('arrow')}</button></form>`;openModal('A time for your care.','Dr. Waheed Khan · '+esc(data.settings.city),body);updateBookingSlots();updateBookingFee()}
function updateBookingFee(){const summary=$('#booking-fee-summary');if(!summary)return;const reason=$('#booking-reason')?.value;const fee=reason==='Follow-up consultation'?data.settings.followFee:state.bookingType==='Video'?data.settings.videoFee:data.settings.fee;summary.textContent=`Illustrative consultation fee: ₹${Number(fee).toLocaleString('en-IN')} · No payment is processed.`}
function updateBookingSlots(){const date=$('#booking-date')?.value||state.bookingDate;state.bookingDate=date;const slots=bookingSlots(date,state.bookingType);$('#booking-slots').innerHTML=slots.length?slots.map(t=>`<button type="button" class="slot ${state.bookingSlot===t?'selected':''}" data-action="slot:${t}">${readableTime(t)}</button>`).join(''):'<p class="muted" style="font-size:11px;grid-column:1/-1;padding:15px 0">No slots available. Please select another date.</p>';if(!slots.includes(state.bookingSlot)){state.bookingSlot='';$('#booking-time').value=''}}
function submitBooking(form){const f=Object.fromEntries(new FormData(form));if(!f.time){toast('Please select an available consultation time.');return}if(f.date<today()||!bookingSlots(f.date,state.bookingType).includes(f.time)){toast('That slot is no longer available. Please select another time.');updateBookingSlots();return}let p=data.patients.find(p=>p.phone===f.phone&&p.name.toLowerCase()===f.name.trim().toLowerCase());if(!p){p={id:uid('p'),name:f.name.trim(),phone:f.phone,age:Number(f.age),sex:f.sex,color:'#e7edda',last:f.date};data.patients.push(p)}const appointment={id:uid('a'),patientId:p.id,date:f.date,time:f.time,type:state.bookingType,status:'Waiting',reason:f.reason,payment:f.payment,fee:f.reason==='Follow-up consultation'?data.settings.followFee:state.bookingType==='Video'?data.settings.videoFee:data.settings.fee};data.appointments.push(appointment);save('Appointment booked',p.name+' · '+f.date+' '+f.time);render();openModal('Appointment reserved','Your demo booking is ready.',`<div class="success-state"><div class="success-icon">${icon('check')}</div><h2>We’ve made room for you.</h2><p>${esc(p.name)}, your consultation with Dr. Waheed Khan is reserved in this demo.</p><div class="booking-summary"><strong>${dateText(f.date)} · ${readableTime(f.time)} IST</strong><br>${appointment.type} consultation · ${esc(f.reason)}<br>Demo fee: ₹${esc(appointment.fee)} · ${esc(f.payment)}<br><span class="muted">Booking reference: ${appointment.id.slice(-7).toUpperCase()}</span></div><p>No SMS was sent and no payment was processed.</p></div>`,btn('Done','close-modal','primary','check'))}
function openPatientForm(){openModal('A new connection.','Add a fictional patient to your clinic workspace.',`<form id="patient-form"><div class="field"><label for="patient-name">Full name</label><input name="name" id="patient-name" required maxlength="80"></div><div class="field"><label for="patient-phone">Mobile number</label><input name="phone" id="patient-phone" type="tel" inputmode="numeric" pattern="[6-9][0-9]{9}" maxlength="10" required></div><div class="field-grid"><div class="field"><label for="patient-age">Age</label><input name="age" id="patient-age" type="number" min="0" max="120" required></div><div class="field"><label for="patient-sex">Sex</label><select name="sex" id="patient-sex"><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></div></div><div class="form-note">Please enter fictional information. Records are saved locally in your browser.</div><button class="btn btn-primary" type="submit" style="width:100%">${icon('users')}Add patient</button></form>`)}
function patientHistory(id){const p=patientById(id);if(!p)return;const visits=data.appointments.filter(a=>a.patientId===id).sort((a,b)=>b.date.localeCompare(a.date)),rx=data.prescriptions.filter(r=>r.patientId===id);openModal(esc(p.name),'Patient history · Fictional demo record',`<div class="flex">${avatar(p)}<div style="font-size:12px;line-height:1.8">${p.age} years · ${esc(p.sex)}<br><span class="muted">+91 ${esc(p.phone)}</span></div></div><div class="form-note">Clinical history and vitals below appear only when entered by the doctor. Demo patients have no invented medical diagnoses.</div><h3 style="margin-top:25px">Consultation timeline</h3><div class="timeline">${visits.map(a=>`<div class="timeline-item"><h3>${dateText(a.date)} · ${a.type}</h3><p>${esc(a.reason)}<br>Status: ${a.status}</p>${rx.filter(r=>r.appointmentId===a.id).map(r=>`<button class="btn btn-quiet" data-action="print-rx:${r.id}">View prescription ${icon('arrow')}</button>`).join('')}</div>`).join('')||'<p class="muted" style="font-size:12px">No consultations yet.</p>'}</div>${rx.filter(r=>!r.appointmentId).map(r=>`<div class="record-item"><div><h3>Prescription · ${dateText(r.date)}</h3><p>${esc(r.diagnosis)}</p></div><button class="btn btn-quiet" data-action="print-rx:${r.id}">Open</button></div>`).join('')}`,`${btn('Book a visit','book-patient:'+id,'secondary','calendar')}${btn('Write prescription','rx-patient:'+id,'primary','rx')}`)}
function openConsult(id){const a=data.appointments.find(a=>a.id===id);if(!a)return;const current=data.appointments.find(x=>x.status==='In consultation'&&x.id!==id&&x.date===today());if(current){const p=patientById(current.patientId);openModal('One visit at a time.',`${esc(p.name)} is currently in consultation.`,`<p class="muted" style="font-size:12px;line-height:1.9">Complete the current visit before starting another, so the clinic queue stays accurate.</p>`,btn('Continue current visit','consult:'+current.id,'primary','arrow'));return}if(a.status==='Waiting'){a.status='In consultation';save('Consultation started',patientById(a.patientId).name);render()}const p=patientById(a.patientId);openModal(esc(p.name),`${a.type} consultation · ${readableTime(a.time)} IST`,`${a.type==='Video'?`<div class="video-room"><span class="avatar">${esc(initials(p.name))}</span><h3>Video consultation preview</h3><p>No remote participant is connected in this demo.</p><div class="video-controls"><button data-action="camera" aria-label="Preview your local camera">${icon('video')}</button><button data-action="close-modal" class="end-call" aria-label="Close video preview">${icon('phone')}</button></div><video class="camera-preview" id="camera-preview" autoplay muted playsinline hidden></video></div><div class="form-note">Camera preview stays on this device. A real consultation requires a configured video service and secure patient link.</div>`:`<div class="flex">${avatar(p)}<div><h3>${esc(p.name)}</h3><p class="muted" style="font-size:11px;margin-top:5px">${p.age} years · ${esc(a.reason)}</p></div></div><div class="form-note" style="margin-top:25px">The patient is now in consultation. Add your clinical notes and prescription, or mark the visit complete.</div>`}`,`${btn('Patient history','history:'+p.id,'secondary','file')}${btn('Write Rx','rx-visit:'+id,'secondary','rx')}${btn('Complete visit','complete:'+id,'primary','check')}`,a.type==='Video')}
function openRx(patientId='',appointmentId=''){const defaultP=patientId||data.patients[0]?.id;openModal('Care, clearly written.','Digital prescription · Clinical inputs are entered by the doctor.',`<form id="rx-form" data-appointment="${esc(appointmentId)}"><div class="field-grid"><div class="field"><label for="rx-patient">Patient</label><select id="rx-patient" name="patientId" required>${data.patients.map(p=>`<option value="${p.id}" ${p.id===defaultP?'selected':''}>${esc(p.name)} · ${p.age} yrs</option>`).join('')}</select></div><div class="field"><label for="rx-reg">Medical registration number</label><input id="rx-reg" name="registration" placeholder="Enter verified registration no." maxlength="50"></div></div><div class="field"><label for="rx-complaints">Chief complaints / clinical notes</label><textarea name="complaints" id="rx-complaints" rows="2" placeholder="Enter your consultation notes…" maxlength="3000"></textarea></div><div class="field-grid"><div class="field"><label for="rx-bp">Blood pressure</label><input name="bp" id="rx-bp" placeholder="e.g. 120/80 mmHg" maxlength="30"></div><div class="field"><label for="rx-pulse">Pulse / weight / SpO₂</label><input name="vitals" id="rx-pulse" placeholder="Enter measured vitals" maxlength="100"></div></div><div class="field"><label for="rx-diagnosis">Diagnosis / assessment</label><textarea name="diagnosis" id="rx-diagnosis" rows="2" placeholder="Doctor’s assessment" maxlength="2000" required></textarea></div><label>Medicines · Enter verified names and instructions</label><div id="medicine-list">${medicineRow()}</div><button type="button" class="btn btn-quiet" data-action="add-medicine" style="margin:6px 0 13px">${icon('plus')}Add medicine</button><div class="field"><label for="rx-tests">Investigations / instructions</label><textarea name="tests" id="rx-tests" rows="2" placeholder="Recommended investigations and patient instructions" maxlength="2000"></textarea></div><div class="field"><label for="rx-followup">Follow-up date</label><input name="followup" id="rx-followup" type="date" min="${today()}"></div><div class="form-note">No drug recommendations are generated. This demo produces a printable draft; registration details and a doctor’s signature must be verified before clinical use.</div><button type="submit" class="btn btn-primary" style="width:100%">${icon('check')}Save & preview prescription</button></form>`,'',true)}
function medicineRow(){return `<div class="medicine-row"><input class="med-name" placeholder="Medicine + strength" aria-label="Medicine and strength" maxlength="120"><input class="med-dose" placeholder="Dose / frequency" aria-label="Dose and frequency" maxlength="120"><input class="med-duration" placeholder="Duration / notes" aria-label="Duration and instructions" maxlength="120"><button class="icon-btn" style="width:28px" type="button" data-action="remove-medicine" aria-label="Remove medicine">${icon('x')}</button></div>`}
function submitRx(form){const fields=Object.fromEntries(new FormData(form));const medicines=[...form.querySelectorAll('.medicine-row')].map(row=>({name:$('.med-name',row).value.trim(),dose:$('.med-dose',row).value.trim(),duration:$('.med-duration',row).value.trim()})).filter(m=>m.name);const rx={...fields,medicines,id:uid('rx'),date:today(),appointmentId:form.dataset.appointment};data.prescriptions.unshift(rx);save('Prescription draft saved',patientById(rx.patientId).name);render();printRx(rx.id)}
function printRx(id){const r=data.prescriptions.find(r=>r.id===id);if(!r)return;const p=patientById(r.patientId);openModal('Prescription preview','Use your browser’s print dialog to save as PDF.',`<article class="print-rx"><header style="text-align:center;padding:10px 0 20px;border-bottom:2px solid #72915d"><h2>Dr. Waheed Khan</h2><p style="font-size:11px;color:#7b8970;margin:8px 0">Oncologist · ${esc(data.settings.clinic)} · ${esc(data.settings.city)}</p><p style="font-size:10px;color:#8b967f">Registration: ${esc(r.registration||'Not supplied — draft only')}</p></header><div class="flex space" style="margin:22px 0"><div style="font-size:12px;line-height:1.9"><strong>${esc(p.name)}</strong><br>${p.age} years · ${esc(p.sex)}</div><div style="font-size:11px">${dateText(r.date)}</div></div>${r.complaints?`<h3 style="font-size:12px">Clinical notes</h3><p style="font-size:11px;line-height:1.9;margin:6px 0 15px;white-space:pre-line">${esc(r.complaints)}</p>`:''}${r.bp||r.vitals?`<p style="font-size:11px;margin-bottom:16px">Vitals: ${esc(r.bp)} ${esc(r.vitals)}</p>`:''}<h3 style="font-size:12px">Assessment</h3><p style="font-size:11px;line-height:1.9;margin:6px 0 18px;white-space:pre-line">${esc(r.diagnosis)}</p><div style="font-family:Georgia;font-size:30px;margin:10px 0">℞</div>${r.medicines.length?`<div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Dose / frequency</th><th>Duration / instructions</th></tr></thead><tbody>${r.medicines.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.dose)}</td><td>${esc(m.duration)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted" style="font-size:11px">No medicines entered.</p>'}${r.tests?`<h3 style="font-size:12px;margin-top:24px">Investigations / instructions</h3><p style="font-size:11px;line-height:1.9;margin-top:7px;white-space:pre-line">${esc(r.tests)}</p>`:''}${r.followup?`<p style="font-size:12px;margin-top:23px"><strong>Follow-up:</strong> ${dateText(r.followup)}</p>`:''}<div style="margin-top:45px;padding-top:15px;border-top:1px solid #e3e8da;font-size:10px;color:#879477;line-height:1.9">Doctor’s signature: ____________________<br>DEMO DRAFT · Fictional data · Not a valid clinical prescription<br>Clinic address, contact details, and credentials require verification.</div></article>`,`${btn('Close','close-modal','secondary')}${btn('Print / Save PDF','print','primary','download')}`,true)}
function availability(){openModal('Your time, thoughtfully planned.','Manage the demo appointment calendar.',`<form id="availability-form"><div class="field-grid"><div class="field"><label for="start-time">Clinic opens</label><input id="start-time" name="start" type="time" value="${data.settings.start}" required></div><div class="field"><label for="end-time">Clinic closes</label><input id="end-time" name="end" type="time" value="${data.settings.end}" required></div></div><div class="field"><label for="slot-duration">Slot duration</label><select name="duration" id="slot-duration">${[15,20,30,45,60].map(m=>`<option value="${m}" ${Number(data.settings.duration)===m?'selected':''}>${m} minutes</option>`).join('')}</select></div><label>Clinic days</label>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<label class="toggle-row">${d}<input type="checkbox" name="days" value="${d}" ${data.settings.days.includes(d)?'checked':''}></label>`).join('')}<div class="form-note">Lunch break is 1:00–2:00 PM. Existing appointments remain on the calendar when hours change.</div><button class="btn btn-primary" style="width:100%" type="submit">${icon('check')}Save availability</button></form>`)}
function openLogin(){openModal('Your care, in one place.','Try the phone login experience with a demo patient.',`<form id="login-phone-form"><div class="field"><label for="login-phone">Demo mobile number</label><input id="login-phone" name="phone" type="tel" inputmode="numeric" pattern="[6-9][0-9]{9}" maxlength="10" value="9000000001" required></div><div class="form-note">Use 9000000001 for Ananya Sen, a fictional patient. This does not send an SMS or verify your identity.</div><button type="submit" class="btn btn-primary" style="width:100%">Continue to demo code ${icon('arrow')}</button></form>`)}
function demoCode(phone){openModal('A simple way to connect.','Demo verification screen · No SMS has been sent.',`<form id="login-code-form" data-phone="${esc(phone)}"><div class="field"><label for="login-code">Enter demo code</label><input id="login-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="6-digit code" required></div><div class="form-note">The demo code is <strong>123456</strong>. This is a simulation, not real authentication.</div><button class="btn btn-primary" style="width:100%" type="submit">Open demo portal ${icon('arrow')}</button></form>`)}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),demo:true,...data},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='privatepractice-demo-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);save('Data exported','JSON demo export');toast('Demo data exported as JSON.')}
function auditView(){openModal('A visible record of activity.','Browser-local demo log · Not tamper-resistant.',data.audit.length?data.audit.slice(0,50).map(e=>`<div class="record-item" style="padding:15px 0"><div><h3>${esc(e.action)}</h3><p>${esc(e.detail)}<br>${new Date(e.at).toLocaleString('en-IN')}</p></div></div>`).join(''):'<div class="empty-state">Your activity will appear here as you use the demo.</div>',btn('Close','close-modal','primary'))}
function notifications(){openModal('Your clinic, up to date.','Today’s demo activity.',`<div class="form-note">${todayAppointments().filter(a=>a.status==='Waiting').length} patients are waiting for consultation.</div><div class="form-note">${data.prescriptions.length} prescription draft(s) saved in this browser.</div><p class="muted" style="font-size:12px;line-height:1.8;margin-top:20px">Appointment reminders and real-time notifications will be connected in production.</p>`,btn('View queue','go-queue','primary','arrow'))}
function dayView(date){const appts=data.appointments.filter(a=>a.date===date&&a.status!=='Cancelled');openModal(dateText(date,{weekday:'long',day:'numeric',month:'long'}),'Your clinic calendar · IST',appts.length?appts.map(a=>`<div class="record-item"><div><h3>${esc(patientById(a.patientId).name)}</h3><p>${readableTime(a.time)} · ${a.type} · ${a.status}</p></div></div>`).join(''):'<div class="empty-state">No appointments on this day.</div>',date>=today()?btn('Book this date','book-date:'+date,'primary','plus'):btn('Close','close-modal','secondary'))}
function cancelAppointment(id){const a=data.appointments.find(a=>a.id===id);if(!a)return;openModal('Cancel this appointment?','This changes the local demo booking.',`<p style="font-size:12px;line-height:1.9">${esc(patientById(a.patientId).name)}<br>${dateText(a.date)} · ${readableTime(a.time)} IST</p>`,`${btn('Keep appointment','close-modal','secondary')}${btn('Cancel appointment','confirm-cancel:'+id,'danger','x')}`)}
async function camera(){if(state.mediaStream){state.mediaStream.getTracks().forEach(t=>t.stop());state.mediaStream=null;$('#camera-preview').hidden=true;toast('Camera preview stopped.');return}try{if(!navigator.mediaDevices?.getUserMedia)throw Error();const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});const video=$('#camera-preview');if(!video){stream.getTracks().forEach(t=>t.stop());return}state.mediaStream=stream;video.srcObject=stream;video.hidden=false;toast('Local camera preview only. No video is transmitted.')}catch{toast('Camera unavailable or permission declined. The rest of the demo still works.')}}
function blockLeave(){openModal('Make room for yourself.','Block a date from new bookings.',`<form id="leave-form"><div class="field"><label for="leave-date">Unavailable date</label><input id="leave-date" name="date" type="date" min="${today()}" required></div><div class="form-note">Existing appointments are retained. Please reschedule them individually.</div><button class="btn btn-primary" type="submit" style="width:100%">Block this date</button></form>${data.settings.leaveDates.length?`<h3 style="margin:24px 0 10px;font-size:13px">Blocked dates</h3>${data.settings.leaveDates.map(d=>`<div class="toggle-row">${dateText(d)}<button class="btn btn-quiet" data-action="unblock:${d}">Unblock</button></div>`).join('')}`:''}`)}
function action(value,el){const split=value.indexOf(':'),type=split<0?value:value.slice(0,split),arg=split<0?'':value.slice(split+1);switch(type){case 'view':state.view=arg;state.mobile=false;render();break;case 'mode':closeModal();state.mode=arg;state.mobile=false;render();window.scrollTo(0,0);break;case 'mobile':state.mobile=!state.mobile;render();break;case 'filter':state.queueTab=arg;render();break;case 'booking':openBooking();break;case 'book-type':openBooking(arg==='Follow-up'?'In-clinic':arg);if(arg==='Follow-up')$('#booking-reason').value='Follow-up consultation';updateBookingFee();break;case 'booking-type':{const fields=Object.fromEntries(new FormData($('#booking-form')));state.bookingType=arg;openBooking();for(const name of ['name','phone','age','sex','reason']){const field=$(`[name="${name}"]`,$('#booking-form'));if(field)field.value=fields[name]}updateBookingFee();break}case 'slot':state.bookingSlot=arg;$('#booking-time').value=arg;$('#booking-slots').querySelectorAll('.slot').forEach(b=>b.classList.toggle('selected',b.dataset.action==='slot:'+arg));break;case 'add-patient':openPatientForm();break;case 'history':patientHistory(arg);break;case 'book-patient':state.portalPatient=state.mode==='patient'?arg:state.portalPatient;openBooking();{const p=patientById(arg);for(const name of ['name','phone','age','sex'])$(`[name="${name}"]`,$('#booking-form')).value=p[name]}break;case 'consult':openConsult(arg);break;case 'complete':{const a=data.appointments.find(a=>a.id===arg);a.status='Completed';save('Consultation completed',patientById(a.patientId).name);closeModal();render();toast('Visit completed. The queue is up to date.');break}case 'new-rx':openRx();break;case 'rx-patient':openRx(arg);break;case 'rx-visit':{const a=data.appointments.find(a=>a.id===arg);openRx(a.patientId,a.id);break}case 'add-medicine':$('#medicine-list').insertAdjacentHTML('beforeend',medicineRow());break;case 'remove-medicine':el.closest('.medicine-row').remove();break;case 'print-rx':printRx(arg);break;case 'print':window.print();break;case 'availability':availability();break;case 'leave':blockLeave();break;case 'unblock':data.settings.leaveDates=data.settings.leaveDates.filter(d=>d!==arg);save('Date unblocked',arg);render();blockLeave();break;case 'month':state.calendarOffset=arg==='today'?0:state.calendarOffset+Number(arg);render();break;case 'day':dayView(arg);break;case 'book-date':state.bookingDate=arg;openBooking();break;case 'login':openLogin();break;case 'logout':state.portalPatient=null;render();toast('You’ve left the demo patient portal.');break;case 'export':exportData();break;case 'audit':auditView();break;case 'reset':openModal('Start with a fresh workspace?','This removes changes made in this browser.',`<p class="muted" style="font-size:12px;line-height:1.9">Your demo appointments, added patients, prescriptions, and settings will return to the original sample data. Export first if you want to keep them.</p>`,`${btn('Keep my changes','close-modal','secondary')}${btn('Reset demo','confirm-reset','danger','refresh')}`);break;case 'confirm-reset':data=seed();save();state.portalPatient=null;state.search='';state.patientSearch='';closeModal();render();toast('Demo workspace reset.');break;case 'notifications':notifications();break;case 'go-queue':closeModal();state.mode='doctor';state.view='appointments';render();break;case 'cancel':cancelAppointment(arg);break;case 'confirm-cancel':{const a=data.appointments.find(a=>a.id===arg);a.status='Cancelled';save('Appointment cancelled',patientById(a.patientId).name);closeModal();render();toast('Demo appointment cancelled.');break}case 'chat':state.chatOpen=!state.chatOpen;renderChat();if(state.chatOpen)$('#chat-input')?.focus();break;case 'prompt':chatReply(arg);break;case 'close-modal':closeModal();break;case 'camera':camera();break}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el)}else if(e.target.classList.contains('modal-overlay'))closeModal()});
document.addEventListener('submit',e=>{const form=e.target;e.preventDefault();switch(form.id){case 'booking-form':submitBooking(form);break;case 'patient-form':{const f=Object.fromEntries(new FormData(form));if(data.patients.some(p=>p.phone===f.phone)){toast('A demo patient with this phone number already exists.');return}data.patients.push({...f,name:f.name.trim(),age:Number(f.age),id:uid('p'),color:'#e7edda',last:today()});save('Patient added',f.name);closeModal();render();toast('Patient added to your demo clinic.');break}case 'rx-form':submitRx(form);break;case 'settings-form':{Object.assign(data.settings,Object.fromEntries(new FormData(form)));save('Clinic settings updated');render();toast('Clinic details saved.');break}case 'availability-form':{const f=new FormData(form),start=f.get('start'),end=f.get('end'),days=f.getAll('days');if(start>=end){toast('Closing time must be later than opening time.');return}if(!days.length){toast('Please select at least one clinic day.');return}Object.assign(data.settings,{start,end,duration:f.get('duration'),days});save('Availability updated');closeModal();render();toast('Your availability has been updated.');break}case 'leave-form':{const date=new FormData(form).get('date');if(!data.settings.leaveDates.includes(date))data.settings.leaveDates.push(date);save('Date blocked',date);closeModal();render();toast('This date is blocked for new appointments.');break}case 'login-phone-form':{const phone=new FormData(form).get('phone');if(!data.patients.some(p=>p.phone===phone)){toast('Use an existing demo patient number, such as 9000000001.');return}demoCode(phone);break}case 'login-code-form':{if(new FormData(form).get('code')!=='123456'){toast('The demo code is 123456.');return}state.portalPatient=data.patients.find(p=>p.phone===form.dataset.phone).id;closeModal();render();toast('Demo portal opened. This is simulated authentication.');break}case 'chat-form':{const text=$('#chat-input').value.trim();if(text)chatReply(text);break}}});
document.addEventListener('input',e=>{if(e.target.id==='queue-search'){const start=e.target.selectionStart;state.search=e.target.value;render();const field=$('#queue-search');field.focus();field.setSelectionRange(start,start)}if(e.target.id==='patient-search'){const start=e.target.selectionStart;state.patientSearch=e.target.value;render();const field=$('#patient-search');field.focus();field.setSelectionRange(start,start)}});
document.addEventListener('change',e=>{if(e.target.id==='booking-reason')updateBookingFee();if(e.target.id==='booking-date'){state.bookingSlot='';updateBookingSlots()}if(e.target.id==='report-upload'){const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Please choose a report under 10 MB.');e.target.value='';return}if(!/\.(pdf|jpe?g|png)$/i.test(f.name)){toast('Choose a PDF, JPG, or PNG report.');e.target.value='';return}data.uploads.push({id:uid('u'),patientId:state.portalPatient,name:f.name,size:f.size,type:f.type,at:new Date().toISOString()});save('Report metadata added',f.name);render();toast('Report name saved. The file itself was not uploaded.')}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action^="remove-upload:"]');if(button){const id=button.dataset.action.split(':')[1];data.uploads=data.uploads.filter(u=>u.id!==id);save('Report metadata removed');render();toast('Report metadata removed.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').children.length)closeModal();else if(state.chatOpen){state.chatOpen=false;renderChat()}else if(state.mobile){state.mobile=false;render()}}if(e.key==='Tab'&&$('#modal-root').children.length){const focusable=[...$('#modal-root').querySelectorAll('button,input:not([type="hidden"]),select,textarea,a[href]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
